#![allow(clippy::excessive_precision)]

use thermopack_rs::hardsphere_wca::{
    cavity_distribution_function, hard_sphere_diameter, lj_boltzmann_factor, minimum_cavity_radius,
};

const ATOL: f64 = 1.0e-13;
const RTOL: f64 = 1.0e-11;

#[test]
fn white_bear_terms_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/white_bear.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let temperature: f64 = parts[0].parse().unwrap();
        let eps_divk: f64 = parts[1].parse().unwrap();
        let eta: f64 = parts[2].parse().unwrap();
        let r_star: f64 = parts[3].parse().unwrap();
        let r_star_t: f64 = parts[4].parse().unwrap();
        let r_star_tt: f64 = parts[5].parse().unwrap();
        let source: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let (r_min, r_min_t, r_min_tt) = minimum_cavity_radius(temperature, eps_divk);
        let distribution = cavity_distribution_function(eta, r_star, r_star_t, r_star_tt);
        let (e, e_t, e_tt) =
            lj_boltzmann_factor(r_star, r_star_t, r_star_tt, temperature, eps_divk);
        let (diameter, diameter_t, diameter_tt) = hard_sphere_diameter(1.0, eps_divk, temperature);
        let native = [
            r_min,
            r_min_t,
            r_min_tt,
            distribution.value,
            distribution.packing_fraction,
            distribution.packing_fraction_second,
            distribution.temperature,
            distribution.temperature_second,
            distribution.packing_fraction_temperature,
            e,
            e_t,
            e_tt,
            diameter,
            diameter_t,
            diameter_tt,
        ];
        assert_eq!(native.len(), source.len(), "{case}");
        for (position, (source, native)) in source.iter().zip(native.iter()).enumerate() {
            assert!(
                (source - native).abs() <= ATOL + RTOL * source.abs(),
                "{case} entry {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 5);
}

#[test]
fn the_cavity_distribution_is_continuous_at_the_limit() {
    // The source switches the correlation at a packing fraction of 0.52, and
    // the two branches agree there.
    let below = cavity_distribution_function(0.52, 1.1, 1.0e-4, 1.0e-7);
    let above = cavity_distribution_function(0.52 + 1.0e-9, 1.1, 1.0e-4, 1.0e-7);
    assert!((below.value - above.value).abs() < 1.0e-6);
    assert!((below.packing_fraction - above.packing_fraction).abs() < 1.0e-5);
}
